SELECT COUNT(*) AS payment_attempts_jan_2026
FROM payments
WHERE payment_date >= DATE '2026-01-01' AND payment_date < DATE '2026-02-01';

SELECT SUM(refund_amount) AS total_refunded_april_2026
FROM refunds
WHERE refund_date >= DATE '2026-04-01' AND refund_date <= DATE '2026-04-30';

SELECT SUM(refund_amount) AS refunds_may
FROM refunds
WHERE refund_date >= '2026-05-01' AND refund_date < '2026-06-01';
